"use strict";
const crypto = require('crypto');
const http = require('http');

// Session token format: base64(userId:timestamp:hmac)
const SECRET_KEY = process.env.SESSION_SECRET || crypto.randomBytes(32);
const TOKEN_MAX_AGE_MS = 3600000; // 1 hour

// Password hashing parameters (scrypt: slow, salted KDF)
const SCRYPT_KEYLEN = 64;
const SCRYPT_SALT_BYTES = 16;

function hashPassword(password) {
  const salt = crypto.randomBytes(SCRYPT_SALT_BYTES);
  const derived = crypto.scryptSync(password, salt, SCRYPT_KEYLEN);
  return `${salt.toString('hex')}:${derived.toString('hex')}`;
}

function verifyPassword(password, stored) {
  if (typeof stored !== 'string') return false;
  const sep = stored.indexOf(':');
  if (sep === -1) return false;
  const saltHex = stored.substring(0, sep);
  const expectedHex = stored.substring(sep + 1);
  let salt;
  try {
    salt = Buffer.from(saltHex, 'hex');
  } catch (e) {
    return false;
  }
  const derived = crypto.scryptSync(password, salt, SCRYPT_KEYLEN).toString('hex');
  return safeCompare(derived, expectedHex);
}

class TokenStore {
  constructor() {
    this.revokedTokens = new Map();
    this.cleanupInterval = setInterval(() => this._cleanup(), 60000);
  }

  revoke(tokenHash) {
    this.revokedTokens.set(tokenHash, Date.now());
  }

  isRevoked(tokenHash) {
    return this.revokedTokens.has(tokenHash);
  }

  _cleanup() {
    const cutoff = Date.now() - TOKEN_MAX_AGE_MS * 2;
    for (const [hash, timestamp] of this.revokedTokens) {
      if (timestamp < cutoff) this.revokedTokens.delete(hash);
    }
  }
}

const tokenStore = new TokenStore();

/**
 * Constant-time comparison to prevent timing attacks.
 * Uses Node.js built-in timingSafeEqual for guaranteed constant-time behavior.
 */
function safeCompare(a, b) {
  if (!Buffer.isBuffer(a)) a = Buffer.from(a, 'utf8');
  if (!Buffer.isBuffer(b)) b = Buffer.from(b, 'utf8');

  if (a.length !== b.length) return false;

  return crypto.timingSafeEqual(a, b);
}

function generateToken(userId) {
  const timestamp = Date.now().toString(36);
  const payload = `${userId}:${timestamp}`;
  const hmac = crypto.createHmac('sha256', SECRET_KEY)
    .update(payload)
    .digest('hex');
  return Buffer.from(`${payload}:${hmac}`).toString('base64url');
}

function parseToken(token) {
  try {
    const decoded = Buffer.from(token, 'base64url').toString('utf8');
    const lastColon = decoded.lastIndexOf(':');
    if (lastColon === -1) return null;

    const payload = decoded.substring(0, lastColon);
    const providedHmac = decoded.substring(lastColon + 1);

    const firstColon = payload.indexOf(':');
    if (firstColon === -1) return null;

    const userId = payload.substring(0, firstColon);
    const timestamp = payload.substring(firstColon + 1);

    return { userId, timestamp, payload, providedHmac };
  } catch (e) {
    return null;
  }
}

function validateToken(token) {
  const parsed = parseToken(token);
  if (!parsed) return { valid: false, reason: 'malformed' };

  const { userId, timestamp, payload, providedHmac } = parsed;

  // Check token age
  const tokenTime = parseInt(timestamp, 36);
  const age = Date.now() - tokenTime;
  if (age > TOKEN_MAX_AGE_MS || age < 0) {
    return { valid: false, reason: 'expired' };
  }

  // Check revocation
  const tokenHash = crypto.createHash('sha256').update(token).digest('hex');
  if (tokenStore.isRevoked(tokenHash)) {
    return { valid: false, reason: 'revoked' };
  }

  // Compute expected HMAC
  const expectedHmac = crypto.createHmac('sha256', SECRET_KEY)
    .update(payload)
    .digest('hex');

  // Verify HMAC using constant-time comparison
  if (!safeCompare(providedHmac, expectedHmac)) {
    return { valid: false, reason: 'invalid_signature' };
  }

  return { valid: true, userId };
}

// Rate limiting with sliding window
class RateLimiter {
  constructor(windowMs, maxRequests) {
    this.windowMs = windowMs;
    this.maxRequests = maxRequests;
    this.windows = new Map();
  }

  isAllowed(key) {
    const now = Date.now();
    const windowStart = now - this.windowMs;

    if (!this.windows.has(key)) {
      this.windows.set(key, []);
    }

    const requests = this.windows.get(key).filter(t => t > windowStart);
    this.windows.set(key, requests);

    if (requests.length >= this.maxRequests) return false;
    requests.push(now);
    return true;
  }
}

const rateLimiter = new RateLimiter(60000, 100);

// Permission system
const PERMISSIONS = {
  admin: ['read', 'write', 'delete', 'admin'],
  editor: ['read', 'write'],
  viewer: ['read']
};

class UserDatabase {
  constructor() {
    this.users = new Map();
  }

  getUser(userId) {
    return this.users.get(userId) || null;
  }

  createUser(userId, role, passwordHash) {
    this.users.set(userId, { userId, role, passwordHash, createdAt: Date.now() });
  }

  getUserRole(userId) {
    const user = this.getUser(userId);
    return user ? user.role : null;
  }
}

const userDb = new UserDatabase();

function checkPermission(userId, requiredPermission) {
  const role = userDb.getUserRole(userId);
  if (!role) return false;
  const perms = PERMISSIONS[role];
  if (!perms) return false;
  return perms.includes(requiredPermission);
}

// API handlers
function handleLogin(req, body) {
  try {
    const { userId, password } = JSON.parse(body);
    if (!userId || !password) {
      return { status: 400, body: { error: 'Missing credentials' } };
    }

    const user = userDb.getUser(userId);
    if (!user) {
      // Perform dummy comparison to prevent user enumeration via timing
      const dummyHash = crypto.createHash('sha256').update('dummy').digest('hex');
      safeCompare(dummyHash, dummyHash);
      return { status: 401, body: { error: 'Invalid credentials' } };
    }

    // Verify password using salted scrypt KDF with constant-time comparison
    if (!verifyPassword(password, user.passwordHash)) {
      return { status: 401, body: { error: 'Invalid credentials' } };
    }

    const token = generateToken(userId);
    return { status: 200, body: { token } };
  } catch (e) {
    return { status: 400, body: { error: 'Invalid request' } };
  }
}

function handleProtectedResource(req, token, requiredPerm) {
  const validation = validateToken(token);
  if (!validation.valid) {
    return { status: 401, body: { error: validation.reason } };
  }

  if (!checkPermission(validation.userId, requiredPerm)) {
    return { status: 403, body: { error: 'Insufficient permissions' } };
  }

  return { status: 200, body: { data: 'protected resource', user: validation.userId } };
}

function handleLogout(req, token) {
  const validation = validateToken(token);
  if (!validation.valid) {
    return { status: 401, body: { error: 'Invalid token' } };
  }

  const tokenHash = crypto.createHash('sha256').update(token).digest('hex');
  tokenStore.revoke(tokenHash);
  return { status: 200, body: { message: 'Logged out' } };
}

const server = http.createServer((req, res) => {
  const clientIp = req.socket.remoteAddress;

  if (!rateLimiter.isAllowed(clientIp)) {
    res.writeHead(429, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ error: 'Rate limited' }));
    return;
  }

  let body = '';
  req.on('data', chunk => { body += chunk; });
  req.on('end', () => {
    let response;
    const token = (req.headers.authorization || '').replace('Bearer ', '');

    if (req.url === '/login' && req.method === 'POST') {
      response = handleLogin(req, body);
    } else if (req.url === '/resource' && req.method === 'GET') {
      response = handleProtectedResource(req, token, 'read');
    } else if (req.url === '/logout' && req.method === 'POST') {
      response = handleLogout(req, token);
    } else {
      response = { status: 404, body: { error: 'Not found' } };
    }

    res.writeHead(response.status, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify(response.body));
  });
});

module.exports = { server, generateToken, validateToken, parseToken, safeCompare, hashPassword, verifyPassword, userDb, tokenStore };
